const JOURNEYS = [{"id":"PU-01","epic":"E1","name":"Punch in with optional Odoo project","actor":"Hourly employee","story":"As an hourly employee, I want to start my shift with the right optional Odoo project and UKG labor categories so that my time is recorded in the right work context.","trigger":"Employee starts work","pre":"Signed in through SSO and punched out. Odoo Project and Task / LOB may be left blank in the prototype; production project-requiredness remains open.","flow":"1. Open Punch while Out. 2. Optionally select an active assigned Odoo Project and Task / LOB. 3. Optionally use Add Transfer or Recent Transfer to stage UKG labor categories. 4. Tap Punch In. 5. See a brief confirmation with the local time and project details when present.","alt":"No active assigned Odoo projects -> leave Odoo fields blank in the prototype; production behavior depends on the project-requiredness decision. Already punched in -> Punch In is not offered.","rules":"Odoo Project / Task / LOB and UKG Labor Category values are separate. No automatic mapping is implied. Project-requiredness remains open.","api":"POST /v1/timekeeping/timecard (punches.add, action PUNCH_IN, transfer.project)","ev":"Proposed - project-requiredness and integration remain open","src":"Global Time Entry UI/UX Specification §5.1.1–5.1.2, §9","pri":"Must","cov":"Covered","demo":["ava","punch","punch-in","Ava Mitchell > Punch > Punch In"],"q":"Q-06","ac":["I am punched out and may leave project fields blank","I tap Punch In","I see a confirmation with local time and project details when UKG accepts the punch"],"specStatus":"Open decision","specRef":"§5.1.1–5.1.2, §9"},{"id":"PU-02","epic":"E1","name":"Punch out to end the shift","actor":"Hourly employee","story":"As an hourly employee, I want to punch out at the end of my shift so that my shift closes with an accurate total.","trigger":"Employee finishes work","pre":"Employee is punched in","flow":"1. Open Punch. 2. Review elapsed shift time. 3. Tap Punch Out. 4. See a brief confirmation with the action and local time.","alt":"On break -> Punch Out also ends the break (break end recorded at the same time).","rules":"Punch Out is only enabled while punched in. Shift total excludes unpaid break time.","api":"POST /v1/timekeeping/timecard (punches.add)","ev":"Confirmed - Spiro documents","src":"SRC-02, SRC-03, SRC-04, SRC-06, FSD TK-1","pri":"Must","cov":"Covered","demo":["ava","punch","punch-out","Ava Mitchell > Punch > Punch Out"],"q":"","ac":[["I am punched in","I tap Punch Out","an OUT punch is recorded and today's row on My Timecard shows the closed segment and daily total"],["I am punched out","I look at the Punch screen","Punch Out is disabled and Punch In is enabled"]],"specStatus":"Documented","specRef":"§5.1.5"},{"id":"PU-03","epic":"E1","name":"Start and end a break","actor":"Hourly employee","story":"As an hourly employee, I want to record my meal break so that unpaid break time is excluded and break rules are met.","trigger":"Employee goes on break","pre":"Employee is punched in","flow":"1. Tap Start Break. 2. Status changes to On break with a break timer. 3. Tap End Break. 4. Work resumes on the same project.","alt":"Break shorter than the configured minimum -> Short break exception on timecard (TC-03).","rules":"Break start closes the current segment; break end opens a new segment on the same project and task. Paid/unpaid and minimum length are country rules.","api":"POST /v1/timekeeping/timecard (punches.add)","ev":"Confirmed - Spiro documents","src":"SRC-02, SRC-03, SRC-04, FSD TK-1","pri":"Must","cov":"Covered","demo":["ava","punch","punch-break","Ava Mitchell > Punch > Start Break"],"q":"Q-04","ac":[["I am punched in on PRJ-4821","I tap Start Break and later End Break","two segments appear on today's timecard row, both on PRJ-4821, and the break is not counted in the daily total"],["my break lasted less than the configured minimum","the timecard is calculated","a Short break exception is shown on that day"]],"specStatus":"Documented","specRef":"§5.1.3, §5.1.8"},{"id":"PU-04","epic":"E1","name":"Stage or change UKG labor categories","actor":"Hourly employee","story":"As an hourly employee, I want to stage or change UKG labor-category values so that my shift is charged to the right category.","trigger":"Work context changes","pre":"Employee is punched in; target project is assigned and active","flow":"1. Select a Recent Transfer or tap Add Transfer. 2. Choose configured UKG labor-category levels in the Transfer drawer. 3. Review and confirm. 4. While Out, categories are staged for the next Punch In; while In, the transfer applies from that point forward.","alt":"While on break, transfer controls are disabled until the break ends.","rules":"UKG Labor Category Project, Task / LOB, Timecard Code, and Function are separate from Odoo Project and Task / LOB. Required levels and defaults remain open; no Odoo-to-UKG mapping is implied.","api":"POST /v1/timekeeping/timecard (punches.add with transfer object)","ev":"Proposed - labor-category profile and mapping remain open","src":"Global Time Entry UI/UX Specification §5.1.4, §9","pri":"Must","cov":"Covered","demo":["ava","punch","punch-transfer","Ava Mitchell > Punch > Transfer"],"q":"Q-12","ac":[["I am Out and choose Add Transfer","I confirm UKG labor categories","they are staged for my next Punch In without implying an Odoo mapping"],["I am In and choose Add Transfer","I confirm UKG labor categories","the transfer applies from that point forward"]],"specStatus":"Open decision","specRef":"§5.1.4, §9"},{"id":"PU-05","epic":"E1","name":"Blocked punch for unassigned or inactive project","actor":"Hourly employee","story":"As Spiro Finance, I want punches blocked on projects that are closed or not assigned so that time is never charged to the wrong PRJ.","trigger":"Employee selects or scans a project","pre":"Odoo assignment sync has run","flow":"1. The employee selects an Odoo Project from the picker. 2. The picker offers active projects assigned to the employee. 3. Validate the selection again when Punch In is submitted. 4. If it became inactive or unassigned, do not record the punch and show a plain-language message.","alt":"The Odoo Project is optional in the prototype and may be left blank. Whether production punches may start without a project remains open.","rules":"Invalid projects are not offered and are revalidated at submission. Odoo Project validation is separate from UKG labor-category validation.","api":"None (CloudApper validation against Odoo assignment cache)","ev":"Confirmed - picker rule; production requiredness remains open","src":"Global Time Entry UI/UX Specification §5.1.2, §5.1.6, §9","pri":"Must","cov":"Covered","demo":["lukas","kiosk","scan-invalid","Lukas Weber > Kiosk > scan MUC-1999 (closed)"],"q":"Q-06","ac":[["project MUC-1999 is closed in Odoo","I scan or select it","I see 'MUC-1999 is closed. Select an active assigned project.' and no punch is recorded"]],"specStatus":"Open decision","specRef":"§5.1.2, §5.1.6, §9"},{"id":"PU-06","epic":"E1","name":"Show actions for the current punch state","actor":"Hourly employee","story":"As an hourly employee, I want to see the punch action available for my current state so that I can continue the punch flow.","trigger":"Employee taps a punch action","pre":"Current punch state known","flow":"1. Open Punch. 2. See actions for the current state: Out, In, or On break. 3. Choose an available action.","alt":"UKG returns an error for a submitted punch -> show the error message returned by UKG.","rules":"Out -> Punch In; In -> Transfer, Start Break, Punch Out; On break -> End Break, Punch Out. CloudApper sends a selected punch to UKG and displays any returned error, including duplicate-punch errors.","api":"None for displaying the available actions; punch submissions are sent to UKG.","ev":"Confirmed - Spiro documents","src":"SRC-06, FSD TK-1","pri":"Must","cov":"Covered","demo":["ava","punch","punch-in","Ava Mitchell > Punch (buttons follow state)"],"q":"","ac":["I am punched in","I look at Punch","I see Transfer, Start Break, and Punch Out; Punch In is unavailable"],"specStatus":"Documented","specRef":"§5.1.1"},{"id":"PU-07","epic":"E1","name":"See punch confirmation and UKG errors","actor":"Hourly employee","story":"As an hourly employee, I want clear feedback after a punch so that I know whether UKG accepted it.","trigger":"A punch is sent to UKG","pre":"Employee selects a Punch action","flow":"1. CloudApper sends the punch to UKG. 2. If UKG accepts it, show a brief confirmation with the action and local time. 3. Show the recorded event and available project, task, or labor-category details in Recent punches.","alt":"UKG returns an error -> display the error message from UKG, including duplicate-punch errors.","rules":"Show a success confirmation when UKG accepts the punch. If UKG returns an error, show the returned message to the employee.","api":"POST /v1/timekeeping/timecard (punches.add; display the result returned by UKG)","ev":"Confirmed - user clarification","src":"Global Time Entry UI/UX Specification §5.1.8","pri":"Should","cov":"Covered","demo":["ava","punch","recent-punches","Ava Mitchell > Punch > Recent punches"],"q":"","ac":["I submit a punch","UKG accepts it","I see a brief confirmation with the action and local time"],"specStatus":"Documented","specRef":"§5.1.8"},{"id":"PU-08","epic":"E1","name":"Display an error returned by UKG","actor":"Hourly employee","story":"As an hourly employee, I want to see an error returned by UKG when it cannot record my punch so that I know what happened.","trigger":"UKG rejects a punch","pre":"CloudApper has sent a punch to UKG","flow":"1. CloudApper sends the punch to UKG. 2. UKG returns an error. 3. CloudApper displays the error message returned by UKG, including duplicate-punch errors.","alt":"UKG accepts the punch -> show a brief confirmation with the action and local time.","rules":"Display the error returned by UKG to the employee.","api":"POST /v1/timekeeping/timecard (punches.add)","ev":"Confirmed - user clarification","src":"Global Time Entry UI/UX Specification §5.1.8","pri":"Must","cov":"Covered","demo":["ava","punch","sim-punch-error","Punch > simulate a duplicate-punch error from UKG"],"q":"","ac":["I send a punch to UKG","UKG returns a duplicate-punch error","I see the error message returned by UKG"],"specStatus":"Documented","specRef":"§5.1.8"},{"id":"PU-09","epic":"E1","name":"Identify at a shared kiosk","actor":"Warehouse employee (Germany and Poland)","story":"As a warehouse employee without a company phone, I want to identify myself at a shared device so that I can punch without using my personal phone.","trigger":"Employee arrives at the shared device","pre":"Shared kiosk device enrolled (shared kiosk account is a working assumption); employee can be matched to a UKG person","flow":"1. Identify at the kiosk (badge scan or employee number; method to be confirmed). 2. Kiosk greets the employee and shows status. 3. Employee acts. 4. Kiosk returns to its home screen after Done or the inactivity timeout.","alt":"Employee not recognised -> 'Not recognised, see your supervisor'.","rules":"Each employee identifies for their own kiosk activity. After the inactivity timeout the kiosk clears the employee's information and returns home. Timeout length and what is cleared are still to be confirmed.","api":"Badge -> person lookup (source to be confirmed)","ev":"Not documented - warehouse kiosk section is to be drafted","src":"Global Time Entry UI/UX Specification §5.5 is to be drafted; existing prototype journey","pri":"Should","cov":"Covered","demo":["lukas","kiosk","kiosk-badge","Lukas Weber > Kiosk > Scan badge"],"q":"UI-OPEN-01","ac":[["I am at the shared kiosk","I scan badge 40-2231","the kiosk shows my name, current status and allowed actions"],["I stop interacting","30 seconds pass or I tap Done","the kiosk returns to the idle badge screen"]],"specStatus":"Not documented","specRef":"§5.5 (to be drafted)"},{"id":"PU-10","epic":"E1","name":"Scan a project barcode to switch project","actor":"Warehouse employee (Germany and Poland)","story":"As a warehouse employee switching jobs many times a day, I want to scan the job barcode so that my time moves to that project without typing.","trigger":"Employee moves to a different job","pre":"Identified at the kiosk; the scanned code maps to an active, assigned project","flow":"1. Scan project barcode. 2. If punched out -> Punch In on that project; if punched in -> Transfer. 3. Confirmation shows project and time.","alt":"Invalid barcode -> PU-05.","rules":"Working assumption: a scan identifies the employee and the project. Barcode content, scan order and fallback behaviour are still to be confirmed. Scans may be batched to reduce call volume.","api":"POST /v1/timekeeping/timecard (transfer); batching via bulk operations [SE-verify]","ev":"Not documented - warehouse kiosk section is to be drafted","src":"Global Time Entry UI/UX Specification §5.5 is to be drafted; existing prototype journey","pri":"Must","cov":"Covered","demo":["lukas","kiosk","kiosk-scan","Lukas Weber > Kiosk > scan BER-1102"],"q":"UI-OPEN-02, Q-10","ac":[["I am punched in on BER-1102","I scan MUC-2077","a transfer to MUC-2077 is recorded at the scan time"],["I am punched out","I scan BER-1102","I am punched in on BER-1102"]],"specStatus":"Not documented","specRef":"§5.5 (to be drafted)"},{"id":"PU-11","epic":"E1","name":"Punch-required populations cannot enter flat hours","actor":"Hourly employee","story":"As Spiro HR, I want hourly populations that need wage-and-hour compliance to use real punches so that we hold compliant records.","trigger":"Hourly employee opens time entry","pre":"Population flag set per employee","flow":"1. Employee opens time entry. 2. Punch-required employees see Punch and Timecard (review) but not flat-hours entry.","alt":"Grid-allowed populations (e.g. Poland transition) see the project hours grid.","rules":"Population rule decides which entry views are available.","api":"Employee Master attribute (source to be confirmed)","ev":"Proposed - needs Spiro validation","src":"SRC-07, SRC-03, FSD SEC-2","pri":"Must","cov":"Partial","demo":["ava","timecard","view-switch","Ava (punch) vs Zofia (grid)"],"q":"Q-02","ac":[["I am in a punch-required population","I open My Timecard","flat-hours entry is not offered and I am directed to Punch"]],"specStatus":"Open decision","specRef":"§5.1.9, §9"},{"id":"TC-01","epic":"E2","name":"Review my hourly timecard","actor":"Hourly employee","story":"As an hourly employee, I want to review my punches, transfers and hours by day so that I can check my time for the selected period.","trigger":"Employee opens My Timecard","pre":"Signed-in hourly employee; own timecard is available for the selected period. Salaried employees use Project Hours.","flow":"1. Open My Timecard from navigation or Recent punches. 2. Review employee, role, selected period dates and loaded time. 3. Review Date, In, Transfer (Project / Task / LOB), Out, Hours, Daily and Period. 4. Inspect read-only details and project/task totals below the grid.","alt":"Breaks, transfers and split shifts create additional rows. Empty days have blank punch/hour cells and no Absence label; active segments show In progress and missing end punches show a read-only Missed punch label.","rules":"My Timecard is for hourly employees only and is read-only. Edit, Comments, Add punch and correction actions are hidden and disabled. Schedule, Pay Code, Shift, separate Exceptions, Audit, UKG Sync and By Pay Code are omitted. Mobile scrolling stays inside the grid.","api":"POST /v1/timekeeping/employee_timecard/multi_read","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.1.10","pri":"Must","cov":"Covered","demo":["ava","timecard","timecard-grid","Ava Mitchell > My Timecard"],"q":"Q-01","ac":[["I am an hourly employee viewing a selected period","I open My Timecard","the seven documented columns, header and project/task totals are shown in a read-only view"],["I view My Timecard","I review the grid and details","no edit, comment, add-punch or correction action is offered"]],"specStatus":"Documented","specRef":"§5.1.10"},{"id":"TC-02","epic":"E2","name":"Switch between pay periods","actor":"Hourly employee","story":"As an hourly employee, I want to move between time periods so that I can review my recorded time.","trigger":"Employee uses period navigation","pre":"Current and previous period data are available.","flow":"1. Open My Timecard and read the displayed date range. 2. Select Previous to review the prior period. 3. Use Today or Next to return to the current period.","alt":"At the available period boundary, the corresponding control is disabled. The prototype exposes only the current and previous periods.","rules":"Navigation changes the date range, daily records and totals. Country pay-period rules remain open; all periods remain read-only.","api":"employee_timecard/multi_read with date range","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.1.10","pri":"Must","cov":"Covered","demo":["ava","timecard","timecard-grid","Ava Mitchell > My Timecard > Previous / Today / Next"],"q":"Q-01","ac":[["I view the current period","I select Previous","the previous period dates, records and totals appear"],["I view the previous period","I select Today or Next","the current period appears and Next is disabled at the current-period boundary"]],"specStatus":"Documented","specRef":"§5.1.10"},{"id":"TC-03","epic":"E2","name":"Open punch and transfer details","actor":"Hourly employee","story":"As an hourly employee, I want to inspect punch times, labor category and transfer information so that I can verify what my timecard records.","trigger":"Employee selects a recorded punch time or transfer","pre":"The selected period contains a recorded In/Out punch or transfer.","flow":"1. Click, tap or right-click a recorded In/Out time or Transfer cell. 2. Review Date, Time and Punch type for a punch, or the full Project/Task allocation and time range for a transfer. 3. Review recorded UKG values in the separate Labor category group. 4. Close the popover, press Escape or click outside.","alt":"When no labor category is recorded, the popover explains this. A truncated Transfer value is shown in full in its details.","rules":"Details remain read-only and have no Edit or Comments actions. Transfer text stays on one line in the grid. Odoo Project/Task values remain separate from UKG labor categories.","api":"POST /v1/timekeeping/employee_timecard/multi_read (simulated detail data)","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.1.10","pri":"Must","cov":"Covered","demo":["ava","timecard","timecard-grid","Ava Mitchell > My Timecard > select an In/Out time or Transfer"],"q":"Q-03","ac":[["I review a recorded In or Out time","I open its details","Date, Time, Punch and recorded Labor category values appear without Edit or Comments"],["a Transfer value is truncated","I open its details","the full allocation and separate Labor category values are readable"]],"specStatus":"Documented","specRef":"§5.1.10"},{"id":"TC-04","epic":"E2","name":"Employee punch editing is an open decision","actor":"Hourly employee","story":"As an hourly employee, I may need to change a recorded In or Out time; whether employee editing will be enabled remains a decision for Spiro.","trigger":"Employee spots an incorrect recorded punch time","pre":"A recorded punch may need a correction; current My Timecard access is read-only.","flow":"1. Review My Timecard and the recorded punch details. 2. The current view provides no Edit or correction-request action. 3. Keep employee punch-edit access open until Spiro confirms Q-05.","alt":"If editing is approved later, define eligible groups, editable periods, reasons, approval handling and direct-save versus Manager-review behavior.","rules":"Punch editing is currently disabled and its controls are hidden. No correction-request route is assumed. Comments, missing-punch addition and employee approval are also unavailable in the current view.","api":"No punch-update call is made from the current read-only view; a future update contract would need confirmation.","ev":"Proposed - employee edit access remains open","src":"Global Time Entry UI/UX Specification §5.1.10; §9, Q-05","pri":"—","cov":"Not prototyped","demo":["ava","timecard","timecard-grid","Ava Mitchell > My Timecard > read-only punch details"],"q":"Q-05","ac":[["I open My Timecard","I review an incorrect or missing punch","no edit or correction-request action is available while Q-05 remains open"]],"specStatus":"Open decision","specRef":"§5.1.10; §9 (Q-05)"},{"id":"TC-07","epic":"E2","name":"Review totals by project and task","actor":"Hourly employee","story":"As an hourly employee, I want to review hours by project and task so that I can check how my time is allocated.","trigger":"Employee reaches Totals below the timecard grid","pre":"Punches and transfers are recorded in the selected period.","flow":"1. Review Totals below the timecard grid. 2. Review hours grouped by project and task. 3. Compare the period total with the running totals in the grid.","alt":"No project hours in the period -> the totals table shows its empty state and a zero period total.","rules":"The current view shows project/task totals only. By Pay Code, overtime and premium breakdowns are absent; future additions remain an open decision.","api":"Calculated from the demo timecard segments; production totals source remains to be verified.","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.1.10","pri":"Must","cov":"Covered","demo":["ava","timecard","totals","Ava Mitchell > My Timecard > Totals"],"q":"Q-08","ac":[["the period contains recorded project hours","I review Totals","the project/task breakdown and period total are shown without a pay-code breakdown"],["the period has no recorded hours","I review Totals","the empty state and zero total appear"]],"specStatus":"Documented","specRef":"§5.1.10"},{"id":"TC-10","epic":"E2","name":"Audit trail is outside the employee timecard view","actor":"Employee, approver, payroll","story":"Timekeeping audit requirements remain separate from the hourly employee My Timecard review screen.","trigger":"Hourly employee opens My Timecard","pre":"The employee timecard view is available.","flow":"1. Open My Timecard. 2. Review daily records, read-only details and project/task totals. No Audit or UKG Sync tab is available.","alt":"System-level audit retention remains a separate requirement outside this employee screen.","rules":"The current employee view omits Audit and UKG Sync. Separate system audit requirements do not add an employee-screen journey.","api":"No employee audit-screen read is made by this journey.","ev":"Out of scope - current employee view","src":"Global Time Entry UI/UX Specification §5.1.10","pri":"—","cov":"Not prototyped","demo":["ava","timecard","timecard-grid","My Timecard has no Audit or UKG Sync view"],"q":"","ac":[["I open My Timecard","I review the available sections","Audit and UKG Sync tabs are absent"]],"specStatus":"Out of scope","specRef":"§5.1.10"},{"id":"GR-01","epic":"E3","name":"Enter hours across projects in a weekly grid","actor":"Salaried employee (and any hourly population approved for grid entry)","story":"As an employee working on several projects, I want to enter hours per project per day in one grid so that I can log my week quickly.","trigger":"Employee records time","pre":"Assigned projects loaded","flow":"1. Open Project hours. 2. Type hours into day cells. 3. Row and column totals update. 4. Save draft.","alt":"Invalid value -> GR-05.","rules":"Hours must be positive, dated and within the permitted work period.","api":"POST /v1/timekeeping/timecard (paycodeEdits / hours with activity) [SE-verify activity shape]","ev":"Confirmed - Spiro documents","src":"SRC-02, SRC-03, SRC-04, SRC-06, FSD TK-2, TK-3","pri":"Must","cov":"Covered","demo":["zofia","grid","grid","Zofia Kowalska > Project hours"],"q":"UI-OPEN-07","ac":[["I have 3 assigned projects","I type 3 on Monday for PL-8804","the row total and Monday total update immediately"]],"specStatus":"Documented","specRef":"§5.2.1–5.2.2"},{"id":"GR-02","epic":"E3","name":"Rows pre-filled from assigned projects","actor":"Employee","story":"As an employee, I want assigned project rows ready in the weekly grid so that I can enter hours without rebuilding the project list.","trigger":"Grid opens for a new week","pre":"Odoo PRJ assignment sync","flow":"1. Open a new week. 2. See a row for each visible assigned project, with seven daily cells and a project total. 3. Use Projects or Manage projects to show or hide assignments; a hidden assignment remains available in Add new > All.","alt":"More than 50 projects -> Copy & Archive fallback (GR-06).","rules":"Odoo Project / Task / LOB and UKG labor-category values remain separate; no mapping is implied. Assignment source and details prefilled onto a row remain open.","api":"Odoo assignment sync (inbound)","ev":"Proposed - project assignment and mapping details remain open","src":"Global Time Entry UI/UX Specification §5.2.1, §9","pri":"Must","cov":"Covered","demo":["zofia","grid","grid","Zofia Kowalska > Project hours"],"q":"UI-OPEN-05","ac":["I have active assigned projects","I open a new week","visible assigned projects have rows and no Odoo-to-UKG mapping is assumed"],"specStatus":"Open decision","specRef":"§5.2.1, §9"},{"id":"GR-03","epic":"E3","name":"Add a project row with quick lookup","actor":"Employee","story":"As an employee on many PRJs, I want to search by PRJ number, client or show so that I find the right project fast.","trigger":"Employee needs a project not in the grid","pre":"Project assigned and active","flow":"1. Tap Add project. 2. Search by number, name, client or umbrella PRJ. 3. Choose task. 4. Row added.","alt":"Project not in list -> contact PM (assignment missing).","rules":"Only assigned, active projects are searchable. Umbrella PRJ shows its child PRJs.","api":"None (CloudApper cache of Odoo assignments)","ev":"Confirmed - Spiro documents","src":"SRC-01, SRC-03, FSD TK-2, TK-3","pri":"Must","cov":"Covered","demo":["zofia","grid","grid-add","Zofia Kowalska > Project hours > Add project"],"q":"Q-13","ac":[["I search 'Warsaw'","results load","only my assigned active projects matching Warsaw are shown"]],"specStatus":"Documented","specRef":"§5.2.1"},{"id":"GR-04","epic":"E3","name":"Mandatory fields enforced per PRJ","actor":"Employee","story":"As a PM, I want required fields (such as task) enforced for my PRJ so that time is not charged without the detail we need.","trigger":"Employee saves or submits","pre":"PRJ has mandatory-field rules","flow":"1. Employee leaves Task empty on a PRJ that requires it. 2. Submit is blocked and the field is highlighted.","alt":"","rules":"Mandatory fields are defined per PRJ.","api":"None (CloudApper validation)","ev":"Confirmed - Spiro documents","src":"SRC-01, FSD TK-2, TK-3","pri":"Must","cov":"Covered","demo":["zofia","grid","grid-add","Zofia > Project hours > Add PL-8810 without a task, enter hours, Submit"],"q":"","ac":[["PL-8810 requires a task","I submit with hours but no task","submit is blocked with 'PL-8810 needs a task'"]],"specStatus":"Documented","specRef":"§5.2.1–5.2.2"},{"id":"GR-05","epic":"E3","name":"Validate hours entered","actor":"Employee","story":"As payroll, I want impossible values rejected so that bad data never reaches UKG.","trigger":"Employee types a value","pre":"","flow":"1. Type a value. 2. Negative, non-numeric, more than 2 decimals, or a day over 24 hours is flagged at once. 3. Submit is blocked until fixed.","alt":"","rules":"Positive, max 2 decimals, daily total <= 24, dates only inside the open pay period (future periods are read-only). Comma or dot decimals accepted for EU locales.","api":"None (CloudApper validation)","ev":"Confirmed - Spiro documents","src":"SRC-06, FSD TK-2, TK-3","pri":"Must","cov":"Covered","demo":["zofia","grid","grid","Zofia Kowalska > Project hours > type 30"],"q":"","ac":[["Monday already has 8 hours","I enter 20 on another row for Monday","the cell is flagged 'Day total cannot exceed 24 hours' and submit is blocked"]],"specStatus":"Documented","specRef":"§5.2.2"},{"id":"GR-06","epic":"E3","name":"Copy last week","actor":"Employee","story":"As an employee on dozens of projects, I want to copy last week's rows so that I only adjust hours.","trigger":"New week","pre":"Previous week has rows","flow":"1. Tap Copy last week. 2. Rows (and optionally hours) copy. 3. Adjust and save.","alt":"Copied project now closed -> row skipped with a note.","rules":"Copy last week is not defined in the current UI/UX specification; its behavior and eligibility remain open.","api":"None","ev":"Proposed - Copy last week is not documented","src":"Journey register Q-13; Global Time Entry UI/UX Specification §5.2.1 does not define Copy last week","pri":"Should","cov":"Covered","demo":["zofia","grid","grid-copy","Zofia Kowalska > Project hours > Copy last week"],"q":"Q-13","ac":[["last week had 4 rows, one now closed","I tap Copy last week","3 rows are copied and I see '1 closed project skipped'"]],"specStatus":"Open decision","specRef":"§5.2.1; Q-13"},{"id":"GR-07","epic":"E3","name":"Show or hide assigned projects","actor":"Employee","story":"As an employee, I want to hide assigned projects I do not use so that the weekly grid stays focused.","trigger":"Employee manages the weekly project list","pre":"Assigned projects are available in Project hours","flow":"1. Choose Projects or Manage projects. 2. Hide an assigned project to remove its row from the visible grid. 3. Find the hidden assignment in Add new > All when needed.","alt":"Hiding a project changes visibility only; it does not remove the employee assignment.","rules":"Hidden assigned projects remain available in the Add new > All list.","api":"None","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.2.1","pri":"Could","cov":"Covered","demo":["zofia","grid","grid","Zofia Kowalska > Project hours > Archive"],"q":"Q-13","ac":["I hide an assigned project","I open Add new > All","the project remains available because hiding did not remove the assignment"],"specStatus":"Documented","specRef":"§5.2.1"},{"id":"GR-08","epic":"E3","name":"Save project hours with the correct employee outcome","actor":"Employee","story":"As an employee, I want to save hours as I enter them so that they are kept with the correct outcome for my employee type.","trigger":"Employee finishes entry","pre":"All rows valid","flow":"1. Enter valid hours. 2. Choose Save. 3. Salaried project hours show Recorded and do not need approval; hourly flat-hours entries show Submitted and enter the configured review flow.","alt":"Validation errors -> submit blocked with the list.","rules":"Drafts are not sent to UKG. Production persistence, UKG integration, and hourly approval routing remain unconfirmed.","api":"POST /v1/timekeeping/timecard on submit","ev":"Confirmed - UI/UX specification; production routing remains open","src":"Global Time Entry UI/UX Specification §5.2.2, §9","pri":"Must","cov":"Covered","demo":["zofia","grid","grid-submit","Zofia Kowalska > Project hours > Submit"],"q":"Q-09","ac":[["all rows are valid","I submit","rows show Submitted and appear in Oliver Grant's approval queue for his projects"]],"specStatus":"Documented","specRef":"§5.2.2"},{"id":"GR-09","epic":"E3","name":"Salaried project time without approval","actor":"Salaried employee","story":"As a salaried employee, I want to record project and task time without punches or an approval step so that it takes me minutes a week.","trigger":"Weekly entry","pre":"Salaried flag; assigned projects","flow":"1. Open Project hours. 2. Enter hours by project and task. 3. Submit. 4. Rows show Recorded (no approval).","alt":"","rules":"Per the Business Requirements, salaried project hours do not require approval.","api":"POST /v1/timekeeping/timecard (activity hours) [SE-verify]","ev":"Confirmed - Spiro documents","src":"SRC-01, SRC-04, FSD TK-2, TK-3","pri":"Must","cov":"Covered","demo":["maya","grid","grid-submit","Maya Chen > Project hours > Submit"],"q":"UI-OPEN-07","ac":[["I am salaried","I submit my week","rows show Recorded and none appear in an approval queue"]],"specStatus":"Documented","specRef":"§5.2"},{"id":"GR-10","epic":"E3","name":"Correct a returned hourly line and save again","actor":"Employee","story":"As an hourly flat-hours employee, I want to see the approver note and correct a returned line so that I can save the revised hours.","trigger":"Approver rejects a line","pre":"A project-time row is returned with an approver note.","flow":"1. Open Project hours. 2. Review the returned row, approver note, and page-level notice. 3. Correct the hours. 4. Save; the row returns to the pending approval flow.","alt":"","rules":"The prototype uses Returned for a line sent back for correction. Project-time approver roles, routing, and review steps remain open.","api":"Notification + timecard update","ev":"Proposed - project-time approval remains open","src":"Global Time Entry UI/UX Specification §5.2.2, §9","pri":"Must","cov":"Covered","demo":["zofia","grid","grid","Reject as Oliver, then open Zofia > Project hours"],"q":"UI-OPEN-06","ac":["an hourly project-time row is returned with a note","I correct the hours and save","the row returns to the pending review flow"],"specStatus":"Open decision","specRef":"§5.2.2, §9"},{"id":"GR-11","epic":"E3","name":"Reminder to enter time","actor":"Employee","story":"As Resource Management, I want employees reminded to enter time so that data is complete for reporting.","trigger":"Scheduled check finds missing time","pre":"Reminder schedule configured","flow":"1. Email (and in-app banner) reminds the employee. 2. Link opens the week to complete.","alt":"","rules":"The prototype reminder says time is due Friday at 17:00. Confirm the production reminder rule and due time before release.","api":"CloudApper notification service","ev":"Proposed - production reminder schedule remains open","src":"Global Time Entry UI/UX Specification §5.2.1, Q-14","pri":"Should","cov":"Partial","demo":["zofia","grid","reminder","Zofia Kowalska > banner"],"q":"Q-14","ac":[["I have not entered Friday's time by the cut-off","the reminder job runs","I get an email and see a banner linking to the open week"]],"specStatus":"Open decision","specRef":"§5.2.1; Q-14"},{"id":"PA-01","epic":"E4","name":"See submitted hours for my projects only","actor":"Line Manager / Project Owner","story":"As a Line Manager / Project Owner, I want a queue of hourly time charged to my projects so that I review only what I own.","trigger":"Hours submitted","pre":"Line Manager / Project Owner maintained per PRJ","flow":"1. Open Approvals. 2. See pending lines grouped by project with employee, days and hours.","alt":"","rules":"Project-time approval is maintained in CloudApper. The project approver may differ from the employee's UKG line manager.","api":"None (CloudApper workflow)","ev":"Proposed - Manager project-time review is not documented in §5.4","src":"Global Time Entry UI/UX Specification §5.4 is to be drafted; project-time approval roles and routing remain open","pri":"Must","cov":"Covered","demo":["oliver","approvals","approvals","Oliver Grant > Approvals"],"q":"UI-OPEN-06, Q-15","ac":[["I approve PRJ-4821 and PRJ-4908 only","I open Approvals","I see lines for those projects and none for other projects"]],"specStatus":"Not documented","specRef":"§5.4 (to be drafted)"},{"id":"PA-02","epic":"E4","name":"Approve one or many lines","actor":"Line Manager / Project Owner","story":"As a Line Manager / Project Owner, I want to approve lines in bulk so that review is fast.","trigger":"Review complete","pre":"Lines pending","flow":"1. Select lines. 2. Approve. 3. Lines move to Approved; employee sees the status.","alt":"","rules":"","api":"Workflow state; UKG write per Q-16","ev":"Proposed - Manager project-time review is not documented in §5.4","src":"Global Time Entry UI/UX Specification §5.4 is to be drafted; project-time approval roles and routing remain open","pri":"Must","cov":"Covered","demo":["oliver","approvals","approvals","Oliver Grant > Approvals > Approve"],"q":"UI-OPEN-06, Q-16","ac":[["I select 3 lines","I tap Approve","all 3 show Approved and the employee's grid shows Approved on those rows"]],"specStatus":"Not documented","specRef":"§5.4 (to be drafted)"},{"id":"PA-03","epic":"E4","name":"Reject a line with a note","actor":"Line Manager / Project Owner","story":"As a Line Manager / Project Owner, I want to reject a line and say why so that the employee can fix it.","trigger":"Wrong project or hours","pre":"Line pending","flow":"1. Tap Reject. 2. Type a note (required). 3. Confirm. 4. Employee is notified (GR-10).","alt":"","rules":"A note is required on rejection.","api":"Workflow + notification","ev":"Proposed - Manager project-time review is not documented in §5.4","src":"Global Time Entry UI/UX Specification §5.4 is to be drafted; project-time approval roles and routing remain open","pri":"Must","cov":"Covered","demo":["oliver","approvals","approvals","Oliver Grant > Approvals > Reject"],"q":"UI-OPEN-06, Q-09","ac":[["I tap Reject","I leave the note empty","the Reject button stays disabled"],["I enter a note","I confirm","the line shows Rejected and the employee sees the note"]],"specStatus":"Not documented","specRef":"§5.4 (to be drafted)"},{"id":"PA-04","epic":"E4","name":"Edit hours on a line with a reason","actor":"Line Manager / Project Owner","story":"As a Line Manager / Project Owner, I want to correct hours directly so that small fixes do not need a rejection loop.","trigger":"Hours slightly wrong","pre":"Line pending","flow":"1. Tap Edit. 2. Enter new hours and reason. 3. Save. 4. Line shows Edited by approver; audit records it.","alt":"","rules":"Reason required; original value kept in audit.","api":"POST /v1/timekeeping/timecard (manager)","ev":"Proposed - Manager project-time review is not documented in §5.4","src":"Global Time Entry UI/UX Specification §5.4 is to be drafted; project-time approval roles and routing remain open","pri":"Must","cov":"Covered","demo":["oliver","approvals","approvals","Oliver Grant > Approvals > Edit"],"q":"UI-OPEN-06","ac":[["a line has 8.0 h","I edit to 7.5 with reason","the line shows 7.5, marked edited, and audit keeps 8.0"]],"specStatus":"Not documented","specRef":"§5.4 (to be drafted)"},{"id":"PA-05","epic":"E4","name":"See budget burn while reviewing","actor":"Line Manager / Project Owner","story":"As a Line Manager / Project Owner, I want to see how much of the estimated hours are used so that I notice overruns early.","trigger":"Approver opens a project group","pre":"Odoo estimated hours synced","flow":"1. Each project shows estimated vs actual with 75/90/100% markers. 2. Lines that push a project over a threshold are flagged.","alt":"","rules":"Estimated hours are not caps on employees. Passing a threshold alone does not require approval; it prompts an internal discussion.","api":"Odoo estimate + UKG actuals","ev":"Proposed - Manager project-time review is not documented in §5.4","src":"Global Time Entry UI/UX Specification §5.4 is to be drafted; project-time approval roles and routing remain open","pri":"Should","cov":"Covered","demo":["oliver","approvals","budget","Oliver Grant > Approvals > budget bar"],"q":"UI-OPEN-06","ac":[["PRJ-4821 is at 88% and a pending line would take it to 92%","I view the queue","the project shows a 90% warning and the line is flagged for discussion, not blocked"]],"specStatus":"Not documented","specRef":"§5.4 (to be drafted)"},{"id":"PA-06","epic":"E4","name":"Approval stays in CloudApper","actor":"System","story":"As payroll, I want project-time approval kept in CloudApper and separate from UKG timecard sign-off so that each process stays clear.","trigger":"Line approved","pre":"","flow":"1. A line is approved or rejected in CloudApper. 2. The decision, note and approver are stored with full history. 3. UKG timecard sign-off continues as a separate process.","alt":"Failure -> reconciliation (PU-08).","rules":"Project-time approval status is maintained in CloudApper and is separate from UKG sign-off. Whether approval gates any UKG write remains open.","api":"POST /v1/timekeeping/timecard","ev":"Proposed - Manager project-time review is not documented in §5.4","src":"Global Time Entry UI/UX Specification §5.4 is to be drafted; project-time approval roles and routing remain open","pri":"Must","cov":"Partial","demo":["oliver","approvals","sync","Oliver Grant > Approvals > UKG sync"],"q":"UI-OPEN-06, Q-16","ac":[["I approve a line","the decision is saved","the line shows Approved with my name, the date and any note, and UKG sign-off is unaffected"]],"specStatus":"Not documented","specRef":"§5.4 (to be drafted)"},{"id":"PA-07","epic":"E4","name":"Return a line for correction","actor":"Line Manager / Project Owner","story":"As a Line Manager / Project Owner, I want to return a line with a note so that the employee can correct it.","trigger":"Line needs a change","pre":"Line pending","flow":"1. Tap Return. 2. Add a note. 3. Confirm. 4. Employee is notified and the line shows Returned.","alt":"","rules":"Returned lines keep full history. Whether Return differs from Reject is still to be confirmed.","api":"Workflow + notification","ev":"Proposed - Manager project-time review is not documented in §5.4","src":"Global Time Entry UI/UX Specification §5.4 is to be drafted; project-time approval roles and routing remain open","pri":"Should","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-06","ac":[["a line is pending","I return it with a note","the employee sees Returned with my note and can correct it"]],"specStatus":"Not documented","specRef":"§5.4 (to be drafted)"},{"id":"PA-08","epic":"E4","name":"Withdraw a submitted line","actor":"Employee","story":"As an employee, I want to withdraw a submitted line that has not been decided so that I can fix a mistake.","trigger":"Employee notices an error","pre":"Line submitted and not yet decided","flow":"1. Open the submitted line. 2. Tap Withdraw. 3. Line leaves the review queue and becomes editable.","alt":"Already decided -> ask the reviewer to return it.","rules":"Decided lines cannot be withdrawn. History is kept.","api":"Workflow","ev":"Proposed - Manager project-time review is not documented in §5.4","src":"Global Time Entry UI/UX Specification §5.4 is to be drafted; project-time approval roles and routing remain open","pri":"Could","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-06","ac":[["my line is pending","I withdraw it","it leaves the queue and I can edit it"]],"specStatus":"Not documented","specRef":"§5.4 (to be drafted)"},{"id":"PA-09","epic":"E4","name":"Item held when no approver is found","actor":"System","story":"As an administrator, I want items with no approver held and flagged so that nothing is silently approved or rejected.","trigger":"Submission has no matching approver","pre":"Routing rules configured","flow":"1. System cannot find an approver. 2. The item is held with status Held. 3. An administrator is alerted.","alt":"","rules":"Items are never auto-approved or auto-rejected.","api":"Workflow + alert","ev":"Proposed - Manager project-time review is not documented in §5.4","src":"Global Time Entry UI/UX Specification §5.4 is to be drafted; project-time approval roles and routing remain open","pri":"Should","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-06","ac":[["no approver is mapped for a project","an employee submits time","the item is held, the employee sees it is waiting, and an administrator is alerted"]],"specStatus":"Not documented","specRef":"§5.4 (to be drafted)"},{"id":"CC-01","epic":"E5","name":"Land on the right time view for my population","actor":"Any employee","story":"As an employee, I want to open the app with SSO and land on the view that fits how I work so that I start right away.","trigger":"Sign in","pre":"SSO configured; population attribute set","flow":"1. Sign in with SSO. 2. Hourly punch users land on Punch; grid users and salaried on Project hours; warehouse on Kiosk.","alt":"","rules":"Role-based views by population.","api":"SSO; Employee Master","ev":"Confirmed - Spiro documents","src":"SRC-02, SRC-04, FSD SEC-1, SEC-2","pri":"Must","cov":"Covered","demo":["ava","home","","Switch persona in the top bar"],"q":"Q-02","ac":[["I am salaried","I sign in","I land on Project hours with no punch controls"]],"specStatus":"Documented","specRef":"§3, §5.1.9, §5.2"},{"id":"CC-02","epic":"E5","name":"Use timecard and punch in my language","actor":"Any employee","story":"As an employee in Europe, I want the timecard in my language with local date formats so that I avoid mistakes.","trigger":"Language set","pre":"","flow":"1. Language follows profile or picker. 2. Labels, dates and numbers localise.","alt":"","rules":"English, French, Dutch, German, Polish with ability to expand.","api":"None","ev":"Confirmed - Spiro documents","src":"SRC-01, SRC-03, FSD UX-1, UX-2","pri":"Must","cov":"Covered","demo":["zofia","grid","lang","Language picker"],"q":"","ac":[["my language is Polski","I open Project hours","labels are in Polish and dates use Polish format"]],"specStatus":"Open decision","specRef":"§5.3.7, §7"},{"id":"CC-03","epic":"E5","name":"Use responsive web on narrow screens","actor":"Any employee","story":"As an employee away from a desk, I want to punch and check my timecard on my phone.","trigger":"Employee on the move","pre":"","flow":"1. Open on phone. 2. Punch screen and timecard adapt to small screens.","alt":"","rules":"Web and mobile (iOS, Android).","api":"None","ev":"Confirmed - Spiro documents","src":"SRC-01, FSD UI-OPEN-03","pri":"Must","cov":"Covered","demo":["ava","punch","","Open the demo on a phone"],"q":"","ac":[["I am on a phone","I open Punch","the clock and buttons fit the screen without horizontal scrolling"]],"specStatus":"Open decision","specRef":"§5.1, §5.2, §9"},{"id":"CC-04","epic":"E5","name":"Keep Odoo and UKG labor categories distinct","actor":"Employee","story":"As an employee, I want to see whether a project or labor-category value was prefilled, and change it, so that my time lands in the right place.","trigger":"Employee opens a punch or the weekly calendar","pre":"Values available from Odoo or context","flow":"1. Choose an optional Odoo Project and Task / LOB where offered. 2. Select UKG labor categories separately through the Transfer or project-hours flow. 3. Do not assume one source prepopulates the other.","alt":"No Odoo Project value is selected -> the employee may leave it blank in the prototype; production project-requiredness remains open.","rules":"Odoo-to-UKG prefill mapping has not been selected. Source fields, mapping, precedence, overrides, refresh timing, and missing or inactive-value handling remain open.","api":"Odoo assignment data","ev":"Proposed - Odoo-to-UKG mapping remains open","src":"Global Time Entry UI/UX Specification §5.1.1–5.1.4, §5.2.1, §9","pri":"Must","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-05, Q-12","ac":["I open project or labor-category fields","I review their source","Odoo Project / Task and UKG labor categories remain separate unless a mapping is approved"],"specStatus":"Open decision","specRef":"§5.1.1–5.1.4, §5.2.1, §9"},{"id":"TO-01","epic":"E6","name":"Review the current balance before submitting","actor":"Employee","story":"As an employee, I want to see the selected request type balance on final review so that I can consider it before submitting.","trigger":"Employee opens Time Off","pre":"Balances synced from UKG","flow":"1. Choose a request type, dates, and duration. 2. On final review, see the current balance for that type with its unit and as-of time. 3. Do not show a projected balance or repeat it on confirmation.","alt":"Current balance cannot be retrieved -> label it unavailable; never present an older balance as current.","rules":"Show a balance only on the final review step before submission.","api":"UKG accrual balances","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.3.1–5.3.3","pri":"Must","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-08","ac":["I review a Time Off request before submission","I reach final review","I see the current selected-type balance with unit and as-of time, not a projected balance"],"specStatus":"Documented","specRef":"§5.3.1–5.3.3"},{"id":"TO-02","epic":"E6","name":"Request Time Off","actor":"Employee","story":"As an employee, I want to request configured Time Off dates and duration so that the request can follow its documented status flow.","trigger":"Employee needs time off","pre":"Leave types configured","flow":"1. Choose an eligible request type. 2. Choose dates and a configured duration. Full Day uses an inclusive date range; Hours and both half-day durations use one date. 3. Add an optional note and review the request, including the current balance. 4. Submit once. 5. Show the request reference, dates, duration, and returned status: Submitted or a confirmed final status.","alt":"Submission or status is uncertain -> preserve entered data and explain the next step without showing a false success.","rules":"Show only configured eligible request types and durations. Do not repeat balance on confirmation. The policy matrix and eligibility remain open.","api":"Time Off request (UKG pattern)","ev":"Confirmed - UI/UX specification; eligibility policy open","src":"Global Time Entry UI/UX Specification §5.3.2–5.3.4, §9","pri":"Must","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-08","ac":["I choose an eligible type, date, and duration","I submit once","I see the request reference, dates, duration, and Submitted or a confirmed final status"],"specStatus":"Open decision","specRef":"§5.3.2–5.3.4, §9"},{"id":"TO-03","epic":"E6","name":"Date rules by leave type and region","actor":"Employee","story":"As an employee, I want clear date rules so that I do not submit a request that will be refused.","trigger":"Employee picks dates","pre":"Regional leave-date rules configured","flow":"1. Choose a request type. 2. Select valid dates and a configured duration. 3. Allow past dates only for Sick Time; all other request types accept today or future dates.","alt":"Undefined regional rule -> the affected check is blocked with a message.","rules":"Full Day accepts an inclusive range. Hours, First Half Day, and Second Half Day each use one date. Any Sick Time lookback limit remains to be configured.","api":"None (CloudApper validation)","ev":"Confirmed - UI/UX specification; remaining policy rules open","src":"Global Time Entry UI/UX Specification §5.3.2–5.3.4, §9","pri":"Should","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-08","ac":[["I choose sick time","I pick yesterday","the date is accepted"],["I choose annual leave","I pick yesterday","I see that this leave type needs a future date"]],"specStatus":"Documented","specRef":"§5.3.2–5.3.4"},{"id":"TO-04","epic":"E6","name":"Track my request status","actor":"Employee","story":"As an employee, I want to see my request status so that I know whether it was approved.","trigger":"Request submitted","pre":"Request exists","flow":"1. Open My requests. 2. See Approved, Refused, Submitted, or Cancelled, who needs to act next when known, and chronological status history or comments.","alt":"Latest status cannot be confirmed -> keep the last confirmed status visible and show an update message with its last-updated time.","rules":"Use the actual UKG Time Off request statuses as the request-status values: Approved, Refused, Submitted, and Cancelled. Do not substitute inferred statuses. Translate displayed labels into the selected language while preserving this status mapping.","api":"UKG status sync","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.3.2–5.3.4","pri":"Must","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-08","ac":[["A request is awaiting action","I open My requests","I see Submitted and who needs to act next when known"],["my manager refused a request with a reason","I open My requests","I see Refused and the manager reason in request history"]],"specStatus":"Documented","specRef":"§5.3.2–5.3.4"},{"id":"TO-05","epic":"E6","name":"Approve or refuse a managed employee request","actor":"Line Manager / Project Owner","story":"As a Manager, I want to review requests for employees I manage so that I can make a clear Time Off decision.","trigger":"Request reaches my queue","pre":"A Submitted request is in the Manager queue for an employee they manage.","flow":"1. Open Requests needing review in the CloudApper custom app. 2. Review the employee, request, dates, units, note, deadline when applicable, and relevant history. 3. Confirm Approve or Refuse. 4. Enter a required reason before Refuse. 5. Save the decision and notify the employee with its result and timestamp.","alt":"No assigned Manager -> exception handling is still open; do not introduce a new request status.","rules":"Managers review only employees they manage. Only Submitted requests can be approved or refused. Refusal requires a reason saved to history and shared with the employee.","api":"Time Off status sent to UKG","ev":"Confirmed - UI/UX specification; no-Manager exception open","src":"Global Time Entry UI/UX Specification §5.3.5–5.3.6, §9","pri":"Must","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-04","ac":[["I refuse a Submitted request without a reason","I try to confirm the decision","Refuse remains unavailable until I enter a reason"],["I enter a reason and confirm Refuse","the decision is saved","the employee sees Refused with the reason"]],"specStatus":"Documented","specRef":"§5.3.5–5.3.6"},{"id":"TO-06","epic":"E6","name":"Automatically approve an eligible request after three days","actor":"System","story":"As Spiro HR, I want an eligible request with no Manager decision after three days to become Approved so that the configured rule can complete it.","trigger":"Three days pass after submission without a Manager decision","pre":"The request remains Submitted and matches the configured eligibility rule.","flow":"1. Check the request against configured eligibility. 2. If it remains Submitted without a Manager decision for three days, set status to Approved. 3. Record the automatic decision, rule, and timestamp in history. 4. Notify the employee and remove it from the Manager review queue.","alt":"Eligibility criteria, how the three days are counted, and exception routing remain open.","rules":"Automatic approval is a CloudApper configuration rule. Keep the actual status Approved; do not create an Auto-approved status.","api":"Configuration","ev":"Confirmed - three-day rule; eligibility and timing details remain open","src":"Global Time Entry UI/UX Specification §5.3.3–5.3.6, §9","pri":"Should","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-04, UI-OPEN-08","ac":["a configured eligible request remains Submitted without a Manager decision for three days","the rule runs","the request becomes Approved and history records the rule and decision time"],"specStatus":"Open decision","specRef":"§5.3.3–5.3.6, §9"},{"id":"TO-07","epic":"E6","name":"Cancel a request only while it is Submitted","actor":"Employee","story":"As an employee, I want to cancel my own Submitted request so that I can change plans.","trigger":"Plans change","pre":"The request belongs to the employee and its current status is Submitted.","flow":"1. Open the request. 2. Choose Cancel. 3. After CloudApper confirms, show Cancelled and keep the request in history.","alt":"Approved, Refused, or Cancelled request -> no employee cancel action is offered.","rules":"Employees cannot edit a submitted request. Cancellation is available only for the employee's own Submitted request.","api":"Time Off status sync","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.3.2–5.3.4","pri":"Could","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"UI-OPEN-08","ac":["my request is Submitted","I cancel it","after confirmation it shows Cancelled and remains in history"],"specStatus":"Documented","specRef":"§5.3.2–5.3.4"}];
